public class Runner {
    record Case(String label, String input, int expected) {}

    public static void main(String[] args) {
        Case[] cases = new Case[]{
            new Case("\"hello\"", "hello", 2),
            new Case("\"HELLO\"", "HELLO", 2),
            new Case("\"AeIoU\"", "AeIoU", 5),
            new Case("\"xyz\"", "xyz", 0),
            new Case("\"\"", "", 0)
        };
        for (Case c : cases) {
            try {
                int actual = Solution.countVowels(c.input);
                if (actual == c.expected) {
                    System.out.println("PASS\t" + c.label);
                } else {
                    System.out.println("FAIL\t" + c.label + "\t" + c.expected + "\t" + actual);
                }
            } catch (Throwable t) {
                System.out.println("ERROR\t" + c.label + "\t" + t.getClass().getSimpleName() + ": " + t.getMessage());
            }
        }
    }
}
